import{_ as a,o as i,c as e,a3 as n}from"./chunks/framework.qCVWde4n.js";const k=JSON.parse('{"title":"如何修改框架本身","description":"","frontmatter":{},"headers":[],"relativePath":"dev/hack.md","filePath":"dev/hack.md","lastUpdated":1791133906000}'),l={name:"dev/hack.md"};function t(o,s,p,r,d,h){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="如何修改框架本身" tabindex="-1">如何修改框架本身 <a class="header-anchor" href="#如何修改框架本身" aria-label="Permalink to &quot;如何修改框架本身&quot;">​</a></h1><p>想加一个新参数、加一个新挂钩、或者改面板界面？这一页讲<strong>在哪里动手</strong>，以及必须遵守的铁律。</p><h2 id="先理解设计原则" tabindex="-1">先理解设计原则 <a class="header-anchor" href="#先理解设计原则" aria-label="Permalink to &quot;先理解设计原则&quot;">​</a></h2><p>整个框架有两条贯穿始终的原则，改任何东西前先记住：</p><div class="tip custom-block"><p class="custom-block-title">原则一：原版值 × 倍率</p><p>参数改的不是「伤害 = 100」，而是「伤害 = 原值 × 倍率」。这样：</p><ul><li>倍率是 <code>1.0</code> 时，与原版<strong>逐字节等价</strong></li><li>不同舰船 / 武器的原始差异全部保留</li><li>游戏更新后参数不会失效</li></ul></div><div class="tip custom-block"><p class="custom-block-title">原则二：任何异常绝不阻断游戏</p><p>所有文件读写、模型加载、参数应用都包在 <code>try/catch</code> 里。出错只记一条日志，<strong>绝不让游戏或启动崩掉</strong>。</p><p>玩家写错配置不该导致游戏打不开。</p></div><h2 id="场景一-加一个新参数" tabindex="-1">场景一：加一个新参数 <a class="header-anchor" href="#场景一-加一个新参数" aria-label="Permalink to &quot;场景一：加一个新参数&quot;">​</a></h2><p>三步。</p><h3 id="_1-在-modconfig-cs-注册" tabindex="-1">1. 在 <code>ModConfig.cs</code> 注册 <a class="header-anchor" href="#_1-在-modconfig-cs-注册" aria-label="Permalink to &quot;1. 在 \`ModConfig.cs\` 注册&quot;">​</a></h3><p>在参数表里加一行（注意 C# 3.0 语法，用 <code>1f</code> 不是 <code>1.0f</code> 也行，但要与现有一致）：</p><div class="language-csharp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ParamDef</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gun.burstMul&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;主炮连发倍率&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>参数：<code>(key, 默认值, 软下限, 软上限, 硬下限, 硬上限, 中文说明)</code>。</p><h3 id="_2-加一个取值的钩子方法" tabindex="-1">2. 加一个取值的钩子方法 <a class="header-anchor" href="#_2-加一个取值的钩子方法" aria-label="Permalink to &quot;2. 加一个取值的钩子方法&quot;">​</a></h3><p>在 <code>TuningHooks</code>（门面类）里加：</p><div class="language-csharp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> float</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GunBurst</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gun.burstMul&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>Get</code> 未注册的键会返回 <code>1.0</code>（安全默认），所以不用怕拼错键导致伤害归零。</p><h3 id="_3-在游戏源码的实际计算点挂钩" tabindex="-1">3. 在游戏源码的实际计算点挂钩 <a class="header-anchor" href="#_3-在游戏源码的实际计算点挂钩" aria-label="Permalink to &quot;3. 在游戏源码的实际计算点挂钩&quot;">​</a></h3><p>找到那个「原版值」算出来的位置，乘上倍率：</p><div class="language-csharp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 原版：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">num </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> baseDamage;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 改后：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">num </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> baseDamage </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TuningHooks.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GunBurst</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">只放大基数，不要动随机序列</p><p>原版伤害计算里常有 <code>num *= Random.Range(0.8f, 1.2f)</code> 这类随机散布。倍率要乘在<strong>随机之前</strong>的基数上，<strong>不要</strong>去改随机范围的上下限——那会破坏原版的分布。</p></div><p><strong>编译通过 = 挂钩绑定成功</strong>（方法名写错会报 <code>CS0103</code>）。</p><h2 id="场景二-加一个一次性注入-像-unlock-allships" tabindex="-1">场景二：加一个一次性注入（像 unlock.allShips） <a class="header-anchor" href="#场景二-加一个一次性注入-像-unlock-allships" aria-label="Permalink to &quot;场景二：加一个一次性注入（像 unlock.allShips）&quot;">​</a></h2><p>如果某个功能是「找到某个对象后执行一次」，而不是「每次计算时乘倍率」：</p><ol><li>在 <code>ModRuntime.cs</code> 的 <code>Update()</code> 里加侦测逻辑（找 <code>Database</code> 等对象）。</li><li>找到后执行注入，包在 <code>try</code> 块内。</li><li>用一个 <code>bool</code> 标记「已执行」，避免每帧重复。</li><li>纯数值赋值、不改数组长度。</li></ol><h2 id="场景三-改面板界面" tabindex="-1">场景三：改面板界面 <a class="header-anchor" href="#场景三-改面板界面" aria-label="Permalink to &quot;场景三：改面板界面&quot;">​</a></h2><p>面板全在 <code>ModPanel.cs</code>，6 个标签页：<code>参数 / Mod / 存档 / 日志 / 状态 / 帮助</code>。</p><h3 id="铁律-全是踩坑换来的" tabindex="-1">铁律（全是踩坑换来的） <a class="header-anchor" href="#铁律-全是踩坑换来的" aria-label="Permalink to &quot;铁律（全是踩坑换来的）&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">面板工程六条铁律</p><ol><li><strong>临时改 <code>GUI.skin</code> 必须成对还原</strong>。在方法开头改了字号/按钮高/滑块把手，方法结尾<strong>一定要改回去</strong>，否则会永久污染全局界面（连悬浮窗小按钮都会变大）。</li><li><strong>每个标签页都必须有 <code>BeginScrollView</code></strong>。内容随版本增长必然溢出，溢出就是「看不见又滚不动」的死内容。</li><li><strong>破坏性按钮（恢复默认 / 删除）一律两段确认</strong>，且确认态要在切页和开关面板时<strong>清零</strong>，防残留误点。</li><li><strong>桌面鼠标尺度的默认值不适用于手机</strong>：字号 16、按钮高 38、滑块把手 36 才够手指用。</li><li><strong>绝不加「长按 N 秒才响应」门槛</strong>。这会让玩家完全打不开面板且毫无提示。防误触只能靠「位置远离操作区 + 点窗外收起」。</li><li><strong>点击/拖动位移阈值要按屏宽比例取</strong>：<code>TapSlop() = max(12, 屏宽*2%)</code>。固定 6px 在手机上必被抖动突破。</li></ol></div><h3 id="触控目标最小-44px" tabindex="-1">触控目标最小 ~44px <a class="header-anchor" href="#触控目标最小-44px" aria-label="Permalink to &quot;触控目标最小 ~44px&quot;">​</a></h3><p>视觉上可以画小，但<strong>判定区必须外扩</strong>（视觉 34px → 判定 54px）。主按钮尤其要注意别与相邻按钮抢点击。</p><h3 id="必须留一条「事件收不到」的逃生通道" tabindex="-1">必须留一条「事件收不到」的逃生通道 <a class="header-anchor" href="#必须留一条「事件收不到」的逃生通道" aria-label="Permalink to &quot;必须留一条「事件收不到」的逃生通道&quot;">​</a></h3><p>部分 Android 抬手时 <code>OnGUI</code> 收不到 <code>MouseUp</code>。所以：</p><ul><li>加<strong>超时兜底</strong>：按下 0.45s 未发生位移就按点击处理（用 <code>realtimeSinceStartup</code>，不用 <code>Time.time</code>，暂停时不卡）</li><li>加<strong>三指同按屏幕强制唤起</strong>（走 <code>Input.touches</code>，完全不依赖 OnGUI 事件）</li></ul><h2 id="场景四-加一个新的挂载点" tabindex="-1">场景四：加一个新的挂载点 <a class="header-anchor" href="#场景四-加一个新的挂载点" aria-label="Permalink to &quot;场景四：加一个新的挂载点&quot;">​</a></h2><p>框架的启动顺序在 <code>ModBridge.Init()</code>。想看流程从那里读：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ModBridge.Init()</span></span>
<span class="line"><span>  → ModProfile.Load()        // 加载玩家档案</span></span>
<span class="line"><span>  → ModConfig 初始化          // 参数表 + 读覆盖层</span></span>
<span class="line"><span>  → ModLoader.LoadAll()      // 扫 mods/、解析、注入</span></span>
<span class="line"><span>  → ModPanel / ModRuntime     // 界面与运行时驱动</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>加东西尽量挂在既有环节末尾</strong>，不要打乱顺序——顺序错了会出现「参数没读到就注入」这类隐蔽 bug。</p><h2 id="改完必须做的三件事" tabindex="-1">改完必须做的三件事 <a class="header-anchor" href="#改完必须做的三件事" aria-label="Permalink to &quot;改完必须做的三件事&quot;">​</a></h2><ol><li><strong>编译</strong>（<code>python compile.py</code>）→ 退出码 0</li><li><strong>核对汉化无损</strong>（补丁脚本会打印条数，正常 213 条）</li><li><strong>确认定版 APK 未被改动</strong></li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>语法约束 → <a href="/AtlanticFleetSite/docs/dev/cs30-limits">C# 3.0 兼容约束</a></li><li>调试手段 → <a href="/AtlanticFleetSite/docs/dev/logging-api">调试与日志接口</a></li><li>提改动 → <a href="/AtlanticFleetSite/docs/dev/contributing">贡献与规范</a></li></ul>`,41)])])}const g=a(l,[["render",t]]);export{k as __pageData,g as default};
